/**
 * The block registry: block type → manifest + React component (SPEC §4.3: one
 * block library shared by all templates).
 *
 * Do not edit this file to add a block — every block type already has its
 * folder; build the block inside it. Need only schemas/metadata? Import
 * `./manifests` instead so components stay out of your bundle.
 */
import type { BlockType } from '@/schemas/site'
import type { AnyBlockDefinition } from './types'
import { aboutBlock } from './about'
import { announcementBlock } from './announcement'
import { blogListBlock } from './blog-list'
import { bookingBlock } from './booking'
import { caseStudyBlock } from './case-study'
import { clientsBlock } from './clients'
import { contactBlock } from './contact'
import { ctaBlock } from './cta'
import { dividerBlock } from './divider'
import { educationBlock } from './education'
import { embedBlock } from './embed'
import { experienceBlock } from './experience'
import { faqBlock } from './faq'
import { footerBlock } from './footer'
import { freeformBlock } from './freeform'
import { galleryBlock } from './gallery'
import { headerBlock } from './header'
import { heroBlock } from './hero'
import { linkHubBlock } from './link-hub'
import { mediaKitBlock } from './media-kit'
import { newsletterBlock } from './newsletter'
import { pricingBlock } from './pricing'
import { processBlock } from './process'
import { projectsBlock } from './projects'
import { publicationsBlock } from './publications'
import { richTextBlock } from './rich-text'
import { servicesBlock } from './services'
import { skillsBlock } from './skills'
import { statsBlock } from './stats'
import { testimonialsBlock } from './testimonials'
import { videoBlock } from './video'

export const blockRegistry: Record<BlockType, AnyBlockDefinition> = {
  hero: heroBlock,
  about: aboutBlock,
  experience: experienceBlock,
  education: educationBlock,
  projects: projectsBlock,
  caseStudy: caseStudyBlock,
  skills: skillsBlock,
  services: servicesBlock,
  testimonials: testimonialsBlock,
  clients: clientsBlock,
  stats: statsBlock,
  gallery: galleryBlock,
  video: videoBlock,
  process: processBlock,
  faq: faqBlock,
  pricing: pricingBlock,
  cta: ctaBlock,
  contact: contactBlock,
  booking: bookingBlock,
  newsletter: newsletterBlock,
  linkHub: linkHubBlock,
  mediaKit: mediaKitBlock,
  publications: publicationsBlock,
  blogList: blogListBlock,
  richText: richTextBlock,
  embed: embedBlock,
  freeform: freeformBlock,
  divider: dividerBlock,
  header: headerBlock,
  footer: footerBlock,
  announcement: announcementBlock,
}

export function getBlock(type: BlockType): AnyBlockDefinition | undefined {
  return blockRegistry[type]
}
